// 구현과 분리된 가상 데이터. 실제 API·인증·서비스 라우팅은 호출하지 않는다.
const params=new URLSearchParams(location.search);
const variant=document.querySelector('#variant'), count=document.querySelector('#count'), state=document.querySelector('#state');
variant.value=params.get('variant')==='b'?'b':'a';count.value=['1','2','3','7'].includes(params.get('count'))?params.get('count'):'3';state.value=['empty','loading','error'].includes(params.get('state'))?params.get('state'):'success';
const titles=['퇴근 후 마음챙김 명상','호흡으로 시작하는 아침','일상 속 스트레스 돌봄과 깊은 이완을 위한 명상','주말 바디스캔','잠들기 전 이완 명상','집중을 위한 마음 훈련','마음챙김 기초'];
const link=(text,path,cls='')=>`<a class="${cls}" href="${path}" data-service>${text}</a>`;
const head=(title,text='전체 보기',path='/app/classes')=>`<div class="section-head"><h2>${title}</h2>${link(text,path)}</div>`;
function render(){
 const n=Number(count.value),s=state.value;
 document.querySelector('#description').textContent=variant.value==='a'?'A · 히어로 전폭 → 좌측 내 클래스·이번 주 클래스·리포트 / 우측 요약 2×2·담당 상담사·대화·알림':'B · 히어로 전폭 → 요약 타일 한 줄 → 내 클래스 전폭 줄 → 아래 일정·리포트 / 담당 상담사·대화·알림';
 const cards=titles.slice(0,n).map((title,i)=>`<article class="class-card">${link(`<span class="chip">${i===6?'예정':'진행 중'}</span><h3>${title}</h3><div class="muted">클래스 진행 ${i===6?0:3}/${i===6?6:8}<div class="progress"><i style="width:${i===6?0:37.5}%"></i></div></div><p class="muted">다음 회차 · ${i===6?1:4}회차</p><div class="meta"><div>10월 ${20+i}일 (${['화','수','목','금','토','일','월'][i]}) 오후 ${i%2?7:8}:00</div><div>지도사 · ${i%2?'박지훈':'이서연'}</div></div>`,`/app/classes/demo-${i+1}`)}</article>`).join('');
 const messages={empty:'아직 클래스가 없어요',loading:'불러오는 중이에요',error:'목록을 불러오지 못했어요'};
 const classes=`<section class="section class-section">${head('내 클래스')} ${s==='success'?`<div class="scroll-wrap"><div class="edge left" hidden></div><div class="track" tabindex="0" aria-label="내 클래스 가로 스크롤">${cards}</div><div class="edge right"></div></div><div class="scroll-tools"><small class="position"></small><button class="prev" aria-label="이전 클래스">←</button><button class="next" aria-label="다음 클래스">→</button></div>`:`<div class="panel state" role="${s==='error'?'alert':'status'}" aria-busy="${s==='loading'}">${messages[s]}${s==='error'?'<button id="retry">다시 시도</button>':''}</div>`}</section>`;
 const tiles=`<div class="tiles" aria-label="요약">${[['다음 클래스까지','D-DAY','클래스 보기','/app/sessions/demo-1'],['새 리포트','2','바로 확인','/app/reports'],['이번 주 클래스',String(Math.min(n,3)),'목록 보기','/app/classes'],['완료 클래스','8','리포트 보기','/app/reports']].map(([label,value,action,path])=>link(`<small>${label}</small><strong>${s==='success'?value:'—'}</strong><span>${action} ›</span>`,path,'tile')).join('')}</div>`;
 const week=`<section class="panel section">${head('이번 주 클래스',`${Math.min(n,3)}개`)}${titles.slice(0,Math.min(n,3)).map((t,i)=>link(`<span class="date">10.${20+i}<br><small>${['화','수','목'][i]}</small></span><div><strong>${t}</strong><p>${i%2?'박지훈':'이서연'} · ${i%2?'19':'20'}:00 · 4회차</p></div><span class="chip">예정</span>`,`/app/sessions/demo-${i+1}`,'row')).join('')}${link('코드로 입장하기 →','/join','code')}</section>`;
 const reports=`<section class="panel section">${head('내 리포트','전체 보기','/app/reports')}${[0,1].map((i)=>link(`<div><strong><span class="chip">NEW</span> ${titles[i]}</strong><p>10월 ${19-i}일 · 몸·마음 변화 리포트</p></div><span>›</span>`,`/app/reports?report=demo-${i+1}`,'row')).join('')}</section>`;
 const secondary=`<section class="panel section">${head('담당 상담사','상담 신청','/app/chat')}<div class="row"><span class="avatar">이</span><div><strong>이서연</strong><p>임상·최면심리상담 전문</p></div></div></section><section class="panel section">${head('최근 대화','전체','/app/chat')}${link('<span class="avatar">이</span><div><strong>이서연 <span class="chip">1</span></strong><p>오늘 클래스에서 뵙겠습니다.</p><small>30분 전</small></div>','/app/chat/demo-1','row')}</section><section class="panel section">${head('새 알림','전체','/app/notifications')}<div class="row"><span class="avatar">•</span><div><strong>리포트가 도착했어요</strong><p>퇴근 후 마음챙김 명상</p><small>1시간 전</small></div></div></section>`;
 const hero=`<section class="hero"><div><span class="chip">다음 일정</span> <span class="chip">명상</span><h2>${s==='success'?'퇴근 후 마음챙김 명상 · 4회차':s==='empty'?'예정된 일정이 없어요':s==='loading'?'일정을 확인하고 있어요':'확인된 예정 일정이 없어요'}</h2>${s==='success'?'<p><b>지도사 · 이서연</b></p><p>10월 20일 (화) 오후 8:00</p>':''}</div>${s==='success'?link('입장하기','/class/demo-1/enter','cta'):''}</section>`;
 const root=document.querySelector('main');root.className=`variant-${variant.value}`;root.innerHTML=hero+(variant.value==='b'?tiles+classes:'')+`<div class="main-column">${variant.value==='a'?classes:''}${week}${reports}</div><aside class="rail">${variant.value==='a'?tiles:''}${secondary}</aside>`;
 const track=document.querySelector('.track');if(track){const update=()=>{const end=track.scrollWidth-track.clientWidth;document.querySelector('.prev').disabled=track.scrollLeft<2;document.querySelector('.next').disabled=track.scrollLeft>=end-2;document.querySelector('.left').hidden=track.scrollLeft<2;document.querySelector('.right').hidden=track.scrollLeft>=end-2;document.querySelector('.position').textContent=end>2?'좌우로 넘겨 모든 클래스 보기':'모든 클래스 표시';};track.addEventListener('scroll',update);track.addEventListener('focusin',event=>{const card=event.target.closest('.class-card');if(card)card.scrollIntoView({block:'nearest',inline:'start',behavior:'instant'});});document.querySelector('.prev').onclick=()=>track.scrollBy({left:-296,behavior:'smooth'});document.querySelector('.next').onclick=()=>track.scrollBy({left:296,behavior:'smooth'});update();}
 document.querySelector('#retry')?.addEventListener('click',()=>{state.value='success';change();});
}
function change(){history.replaceState(null,'',`?variant=${variant.value}&count=${count.value}&state=${state.value}`);render();}
[variant,count,state].forEach(el=>el.addEventListener('change',change));
document.addEventListener('click',e=>{const a=e.target.closest('[data-service]');if(a){e.preventDefault();const notice=document.querySelector('#notice');notice.textContent=`정적 시안 · 이동 대상: ${a.getAttribute('href')}`;notice.style.display='block';setTimeout(()=>notice.style.display='none',2500);}});
render();window.addEventListener('resize',()=>render());
